    }

    .nav {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 1rem 0;
    }

    .logo {
      font-size: 1.8rem;
      font-weight: 800;
      color: #e63946;
      text-transform: uppercase;
      letter-spacing: 1px;
    }
    .logo span {
      color: #1e1e2f;
    }

    .nav-links {
      display: flex;
      gap: 2rem;
      list-style: none;
    }
    .nav-links a {
      text-decoration: none;
      color: #1e1e2f;
      font-weight: 500;
      transition: color 0.2s;
    }
    .nav-links a:hover {
      color: #e63946;
    }

    /* ----- HERO ----- */
    .hero {
      background: linear-gradient(135deg, #fff5f5 0%, #ffe8e8 100%);
      padding: 4rem 0;
      text-align: center;
    }
    .hero h1 {
      font-size: 3.2rem;
      margin-bottom: 1rem;
      color: #1e1e2f;
    }
    .hero h1 span {
      color: #e63946;
    }
    .hero p {
      font-size: 1.3rem;
      max-width: 700px;
      margin: 0 auto 2rem;
      color: #3a3a4a;
    }
    .btn {
      display: inline-block;
      background: #e63946;
      color: white;
      padding: 0.9rem 2.2rem;
      border-radius: 50px;
      text-decoration: none;
      font-weight: 600;
      box-shadow: 0 8px 20px rgba(230,57,70,0.3);
      transition: transform 0.2s, box-shadow 0.2s;
      border: none;
      cursor: pointer;
      font-size: 1rem;
    }
    .btn:hover {
      transform: translateY(-3px);
      box-shadow: 0 12px 28px rgba(230,57,70,0.4);
    }

    /* ----- FEATURES ----- */
    .features {
      padding: 4rem 0;
      background: #ffffff;
    }
    .grid-3 {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 2rem;
    }
    .card {
      background: #f9fafc;
      padding: 2rem 1.8rem;
      border-radius: 20px;
      box-shadow: 0 10px 30px rgba(0,0,0,0.05);
      transition: transform 0.2s, box-shadow 0.2s;
      border-left: 6px solid #e63946;
    }
    .card:hover {
      transform: translateY(-6px);
      box-shadow: 0 20px 40px rgba(0,0,0,0.08);
    }
    .card h3 {
      font-size: 1.5rem;
      margin-bottom: 0.8rem;
    }
    .card p {
      color: #3a3a4a;
    }

    /* ----- GALLERY ----- */
    .gallery {
      padding: 4rem 0;
      background: #f1f3f7;
    }
    .gallery-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
      gap: 1.5rem;
    }
    .gallery-item {
      background: white;
      border-radius: 16px;
      overflow: hidden;
      box-shadow: 0 8px 20px rgba(0,0,0,0.08);
      transition: transform 0.2s;
    }
    .gallery-item:hover {
      transform: scale(1.02);
    }
    .gallery-item img {
      width: 100%;
      height: 200px;
      object-fit: cover;
      display: block;
    }
    .gallery-item .caption {
      padding: 1rem;
      font-weight: 500;
      text-align: center;
      background: white;
    }

    /* ----- CONTACT ----- */
    .contact {
      padding: 4rem 0;
      background: #ffffff;
    }
    .contact-form {
      max-width: 600px;
      margin: 0 auto;
      display: flex;
      flex-direction: column;
      gap: 1.2rem;
    }
    .contact-form input,
    .contact-form textarea {
      padding: 1rem;
      border: 2px solid #e0e4ec;
      border-radius: 12px;
      font-family: inherit;
      font-size: 1rem;
      transition: border-color 0.2s;
    }
    .contact-form input:focus,
    .contact-form textarea:focus {
      outline: none;
      border-color: #e63946;
    }
    .contact-form textarea {
      min-height: 120px;
      resize: vertical;
    }
    .contact-form .btn {
      align-self: flex-start;
    }

    /* ----- FOOTER ----- */
    .footer {
      background: #1e1e2f;
      color: #d0d0e0;
      padding: 2.5rem 0;
      text-align: center;
    }
    .footer p {
      margin-bottom: 0.5rem;
    }
    .footer a {
      color: #e63946;
      text-decoration: none;
    }

    /* ----- RESPONSIVE ----- */
    @media (max-width: 768px) {
      .nav {
        flex-direction: column;
        gap: 1rem;
      }
      .nav-links {
        gap: 1.2rem;
        flex-wrap: wrap;
        justify-content: center;
      }
      .hero h1 {
        font-size: 2.4rem;
      }
      .hero p {
        font-size: 1.1rem;
      }
      .section-title {
        font-size: 1.8rem;
      }
    }
  </style>
</head>
